import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 인사발령 처리 완료 상태는 상태 값 목록에 '완료'가 없어 '마감'으로 표현한다.
const DONE_STATUS = '마감';
// 가정: 게시판 테이블이 없어 boardId는 형식만 검사하고 board_post에 공지로 게시한다.
// 가정: 발령 후 직위(position_after)는 저장할 컬럼이 없어 인사기록카드에는 부서만 반영하고 공고 내용에는 직위를 넣는다.
// 가정: 신규 게시물 알림은 재직자 전원에게 포털 채널로 보낸다.
const NOTICE_CHANNEL = '포털';

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

function appointmentIdOf(req: Request): string {
  const id = req.params['personnelAppointmentId'];
  if (typeof id !== 'string' || !/^\d+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '인사발령 ID가 올바르지 않습니다.');
  }
  return id;
}

function checkBoardId(data: Record<string, unknown>): void {
  const boardId = data['boardId'];
  if (boardId === undefined || boardId === null || boardId === '') {
    return;
  }
  if (typeof boardId !== 'number' || !Number.isFinite(boardId)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '공고 게시 게시판이 올바르지 않습니다.');
  }
}

// 공고 내용에는 공고 목적 항목(발령 구분·일자·부서·직위)만 넣고 개인정보는 제외한다.
async function postAnnouncement(db: Db, id: string, userId: string): Promise<number> {
  const rows = await db.query(
    `INSERT INTO board_post (author_id, post_type, category, title, content, visibility_scope, created_at, updated_at)
     SELECT CAST(:userId AS bigint), '공지', '인사발령',
       '[인사발령] ' || e.name || ' ' || a.appointment_type,
       '발령 구분: ' || a.appointment_type || chr(10) ||
       '발령 일자: ' || to_char(a.appointment_date, 'YYYY-MM-DD') || chr(10) ||
       '발령 부서: ' || d.name || chr(10) ||
       '발령 직위: ' || COALESCE(a.position_after, '-'),
       '전체', now(), now()
     FROM personnel_appointment a
     JOIN employee e ON e.employee_id = a.employee_id
     JOIN department d ON d.department_id = a.department_id
     WHERE a.personnel_appointment_id = CAST(:id AS bigint)
     RETURNING board_post_id AS "boardPostId"`,
    { userId, id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '대상 인사발령을 찾을 수 없습니다.');
  }
  const boardPostId = Number(rows[0].boardPostId);
  await db.execute(
    `INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
     SELECT e.employee_id, :channel, '새 발령공고가 게시되었습니다.', b.title, '안읽음', 'NEW_POST', 'BOARD_POST', b.board_post_id, now(), now()
     FROM employee e
     JOIN board_post b ON b.board_post_id = CAST(:postId AS bigint)
     WHERE e.employment_status = '재직자'`,
    { channel: NOTICE_CHANNEL, postId: boardPostId },
  );
  return boardPostId;
}

@Controller('api/v1')
export class FnSfr01303Controller {
  @Post('/personnel-appointments/:personnelAppointmentId/process')
  @HttpCode(200)
  async processPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = appointmentIdOf(req);
    const data = checks.inputOf(req.body);
    checkBoardId(data);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status", employee_id AS "employeeId", department_id AS "departmentId"
         FROM personnel_appointment
         WHERE personnel_appointment_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '처리 대상 인사발령을 찾을 수 없습니다.');
      }
      if (rows[0].status !== '승인') {
        throw new ApiError(409, 'PERSONNEL_APPOINTMENT_STATUS_MISMATCH', '승인 상태의 인사발령만 처리할 수 있습니다.');
      }
      // 발령 내용을 인사기록카드의 임직원 소속에 반영한다.
      await db.execute(
        `UPDATE employee SET department_id = CAST(:departmentId AS bigint), updated_at = now()
         WHERE employee_id = CAST(:employeeId AS bigint)`,
        { departmentId: String(rows[0].departmentId), employeeId: String(rows[0].employeeId) },
      );
      await db.execute(
        `UPDATE personnel_record SET updated_at = now()
         WHERE employee_id = CAST(:employeeId AS bigint)`,
        { employeeId: String(rows[0].employeeId) },
      );
      await db.execute(
        `UPDATE personnel_appointment
         SET status = :done, processed_by = CAST(:userId AS bigint), processed_at = now(), updated_at = now()
         WHERE personnel_appointment_id = CAST(:id AS bigint)`,
        { done: DONE_STATUS, userId: user.id, id },
      );
      await db.execute(
        `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), 'personnel_appointment', CAST(:id AS bigint), '인사발령 처리', now(),
           '발령 상태 승인 -> 마감, 임직원 부서 반영', '인사발령 처리', now(), now())`,
        { userId: user.id, id },
      );
      const boardPostId = await postAnnouncement(db, id, user.id);
      return { personnelAppointmentId: Number(id), status: DONE_STATUS, boardPostId };
    });
  }

  @Post('/personnel-appointments/:personnelAppointmentId/repost-announcement')
  @HttpCode(200)
  async repostAppointmentAnnouncement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = appointmentIdOf(req);
    const data = checks.inputOf(req.body);
    checkBoardId(data);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status" FROM personnel_appointment
         WHERE personnel_appointment_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '대상 인사발령을 찾을 수 없습니다.');
      }
      // 가정: 처리 완료(마감)된 발령만 재게시할 수 있다.
      if (rows[0].status !== DONE_STATUS) {
        throw new ApiError(409, 'INVALID_STATE', '처리가 끝난 인사발령만 재게시할 수 있습니다.');
      }
      const boardPostId = await postAnnouncement(db, id, user.id);
      return { boardPostId };
    });
  }
}

