import { useState } from 'react';
import { call, Band, Badge, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, RefName } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01303Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [appointmentId, setAppointmentId] = useState<number | string>('');
  const [boardId, setBoardId] = useState<number | string>('');

  const body = (): Row => {
    const b: Row = {};
    if (boardId !== '') {
      b.boardId = boardId;
    }
    return b;
  };

  const process = async () => {
    if (appointmentId === '') {
      throw new Error('처리할 인사발령을 선택하세요.');
    }
    const res = await call('POST', '/personnel-appointments/' + appointmentId + '/process', role, body());
    setResults([res, ...results.filter((r) => r.personnelAppointmentId !== res.personnelAppointmentId)]);
    notify('인사발령을 처리하고 발령공고를 게시했습니다.');
    setOpen(false);
    setAppointmentId('');
    setBoardId('');
  };

  const repost = async (row: Row) => {
    try {
      const res = await call('POST', '/personnel-appointments/' + row.personnelAppointmentId + '/repost-announcement', role, {});
      setResults(results.map((r) => (r.personnelAppointmentId === row.personnelAppointmentId ? { ...r, boardPostId: res.boardPostId } : r)));
      notify('발령공고를 다시 게시했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '재게시에 실패했습니다.');
    }
  };

  return (
    <div>
      <h1>인사발령 처리</h1>
      <Band total={results.length}>
        <button onClick={() => setOpen(true)}>인사발령 처리</button>
      </Band>
      <DataTable
        rows={results}
        empty="아직 처리한 인사발령이 없습니다. 인사발령 처리 버튼으로 승인된 발령을 처리하세요."
        columns={[
          { key: 'personnelAppointmentId', label: '인사발령', render: (r) => <RefName table="personnel_appointment" role={role} value={r.personnelAppointmentId} /> },
          { key: 'status', label: '발령 상태', render: (r) => <Badge value={r.status} /> },
          { key: 'boardPostId', label: '공지·게시물', render: (r) => <RefName table="board_post" role={role} value={r.boardPostId} /> },
          { key: 'action', label: '재게시', render: (r) => <button className="ghost" onClick={() => repost(r)}>발령공고 재게시</button> },
        ]}
      />
      {open && (
        <Drawer title="인사발령 처리" onClose={() => setOpen(false)}>
          <Form onSubmit={process} submit="처리" note="처리하면 발령 내용이 반영되고 발령공고가 게시됩니다.">
            <Field label="인사발령" required wide>
              <LookupSelect table="personnel_appointment" role={role} value={appointmentId} onChange={setAppointmentId} />
            </Field>
            <Field label="공고 게시 게시판">
              <NumberInput value={boardId} onChange={setBoardId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
